from pathlib import Path
import subprocess,json,shutil,os
P=Path(__file__).resolve().parent.parent
es=os.environ.get('ESBUILD_BIN') or (str(P/'node_modules/.bin/esbuild') if (P/'node_modules/.bin/esbuild').exists() else shutil.which('esbuild'))
if not es:
 candidates=list((Path.home()/'.npm/_npx').glob('*/node_modules/esbuild/bin/esbuild'));es=str(candidates[0]) if candidates else None
if not es:raise SystemExit('npm install --ignore-scripts to install build dependencies')
subprocess.run([es,'scripts/scene.js','--bundle','--format=iife','--minify','--alias:three='+str(P/'vendor/three/build/three.module.js'),'--outfile=assets/scene.bundle.js'],cwd=P,check=True)
css='*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;background:#17243e}#root{position:relative;width:100%;height:100%;overflow:hidden}.clip{position:absolute;inset:0}canvas{position:absolute;inset:0;display:block;width:100%;height:100%}'
timeline="const clock={_t:0,get t(){return this._t},set t(v){this._t=v;if(window.renderAt)window.renderAt(v)}};const tl=gsap.timeline({paused:true});tl.to(clock,{t:12,duration:12,ease:'none'},0);window.__timelines={'tsinghua-mem-awakening-wide':tl};"
base='''<!doctype html><html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tsinghua MEM · Awakening · Flowing Galaxy</title><style>CSS</style></head><body><div id="root" data-composition-id="tsinghua-mem-awakening-wide" data-duration="12" data-width="1920" data-height="1080" data-fps="30"><div class="clip" id="hinged-assembly" data-start="0" data-duration="12" data-track-index="1"><canvas id="three-layer" width="1920" height="1080"></canvas></div></div><script src="assets/gsap.min.js"></script><script>TIMELINE</script><script src="assets/scene.bundle.js"></script></body></html>'''.replace('CSS',css).replace('TIMELINE',timeline)
(P/'index.html').write_text(base)
playercss='html,body{height:auto;min-height:100%;background:#121b30;color:#ded7f1;font:14px sans-serif}body{display:flex;align-items:center;flex-direction:column;padding:18px}#frame{width:min(94vw,145vh,1920px);aspect-ratio:16/9;position:relative}#root{width:1920px;height:1080px;transform-origin:top left}.controls{width:min(90vw,760px);display:flex;gap:12px;padding:16px 0;align-items:center}button{background:#342446;color:#f0e6ff;border:1px solid #746085;border-radius:7px;padding:9px 14px;cursor:pointer}input{flex:1;accent-color:#c5a9ed}output{font:12px monospace}'
controls='<div class="controls"><button id="play">播放</button><button id="replay">重播</button><input id="scrub" type="range" aria-label="时间轴" min="0" max="12" step=".001" value="0"><output id="time">0.00 / 12</output></div>'
playerjs="const root=document.getElementById('root');const frame=document.createElement('div');frame.id='frame';root.before(frame);frame.append(root);function size(){root.style.transform='scale('+frame.clientWidth/1920+')'}window.addEventListener('resize',size);size();const play=document.getElementById('play'),scrub=document.getElementById('scrub'),output=document.getElementById('time');const sync=()=>{scrub.value=tl.time();output.textContent=tl.time().toFixed(2)+' / 12';if(tl.time()>=12){tl.pause();play.textContent='播放'}};tl.eventCallback('onUpdate',sync);play.onclick=()=>{if(tl.paused()){if(tl.time()>=12)tl.time(0);tl.play();play.textContent='暂停'}else{tl.pause();play.textContent='播放'}};document.getElementById('replay').onclick=()=>{tl.time(0).play();play.textContent='暂停'};scrub.oninput=()=>{tl.pause().time(Number(scrub.value));window.renderAt(Number(scrub.value));play.textContent='播放';sync()};"
standalone=base.replace('<script src="assets/gsap.min.js"></script>','<script>'+(P/'assets/gsap.min.js').read_text()+'</script>').replace('<script src="assets/scene.bundle.js"></script>','<script>'+(P/'assets/scene.bundle.js').read_text()+'</script>').replace('</head>','<style>'+playercss+'</style></head>').replace('</body>',controls+'<script>'+playerjs+'</script></body>')
(P/'deliverables/Tsinghua-MEM-Awakening-Wide.html').write_text(standalone)
(P/'hyperframes.json').write_text(json.dumps({'paths':{'assets':'assets','blocks':'compositions'},'authoringSkill':'general-video'},indent=2))
(P/'meta.json').write_text(json.dumps({'id':'tsinghua-mem-awakening-wide','name':'Tsinghua MEM — Awakening · Flowing Galaxy'},indent=2))
(P/'package.json').write_text(json.dumps({'name':'tsinghua-mem-awakening-wide','private':True,'scripts':{'build':'python3 scripts/build.py','check':'hyperframes check','render':'hyperframes render --quality high --output deliverables/Tsinghua-MEM-Awakening-Wide-12s.mp4'},'devDependencies':{'hyperframes':'0.8.38','esbuild':'0.25.12'}},indent=2))
print('Built 12-second real geometry composition and offline player')
